
-- NRNL 커뮤니티 게시글 테이블 생성
-- 회원 한 명이 여러 게시글을 작성할 수 있는 1:N 관계

CREATE TABLE community_post (

    -- 게시글 고유번호 (PK)
    -- GENERATED BY DEFAULT AS IDENTITY: 게시글 생성 시 ID 자동 증가
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,

    -- 게시글 작성자의 회원 ID (FK)
    -- users 테이블의 id와 연결됨
    user_id BIGINT NOT NULL,

    -- 게시글 제목 (최대 50자, NULL 불가)
    title VARCHAR(50) NOT NULL,

    -- 게시글 본문
    content TEXT NOT NULL,

    -- 게시글 최초 작성 시간
    created_at TIMESTAMP(6) NOT NULL,

    -- 게시글 마지막 수정 시간
    updated_at TIMESTAMP(6) NOT NULL,


    -- 외래 키(FK) 제약조건
    -- community_post.user_id가 users.id를 참조
    -- 존재하지 않는 회원 ID로 게시글을 생성하는 것을 방지
    CONSTRAINT fk_community_post_user
        FOREIGN KEY (user_id)
        REFERENCES users(id),

    -- 게시글 제목이 공백만으로 이루어지는 것을 방지
    -- TRIM: 문자열 양쪽 공백 제거
    -- LENGTH: 문자열 길이 계산
    -- 공백 제거 후 길이가 0보다 커야 저장 가능
    CONSTRAINT chk_community_post_title_not_blank
        CHECK (LENGTH(TRIM(title)) > 0),

    -- 게시글 본문이 공백만으로 이루어지는 것을 방지
    CONSTRAINT chk_community_post_content_not_blank
        CHECK (LENGTH(TRIM(content)) > 0)
);


-- 인덱스 생성
-- 인덱스: DB에서 원하는 데이터를 빠르게 찾기 위한 자료구조

-- 특정 회원이 작성한 게시글을 빠르게 조회하기 위한 인덱스
-- 예: SELECT * FROM community_post WHERE user_id = 3;
CREATE INDEX idx_community_post_user_id
    ON community_post(user_id);


-- 최신 게시글 목록 조회를 효율적으로 처리하기 위한 인덱스
-- created_at DESC: 작성 시간이 최신인 게시글부터 정렬
-- id DESC: 작성 시간이 같은 게시글은 ID가 큰 순서로 정렬
-- PostgreSQL의 기본 인덱스 방식은 B-tree
CREATE INDEX idx_community_post_created_at
    ON community_post(created_at DESC, id DESC);
